(function(){
  function align(text,delim){
    text=String(text==null?'':text); delim=delim||' ';
    var lines=text.split(/\r\n|\r|\n/).filter(function(l){return l!=='';});
    var rows=lines.map(function(l){ return l.split(delim).map(function(c){return c.trim();}); });
    var cols=rows.reduce(function(m,r){return Math.max(m,r.length);},0);
    var widths=new Array(cols).fill(0);
    rows.forEach(function(r){ r.forEach(function(c,i){ widths[i]=Math.max(widths[i],c.length); }); });
    var out=rows.map(function(r){ return r.map(function(c,i){ return (c+'                          ').slice(0,widths[i]); }).join('  '); }).join('\n');
    return {value:out};
  }
  var API={align:align};
  if(typeof module!=='undefined'&&module.exports)module.exports=API;
  if(typeof window!=='undefined')window.__ColumnForge__=API;
})();
